window.products.push({"id":677313,"name":"Honey Dew Gifts Funny Wooden Signs, Chaos Coordinator, 5 inch by 10 inch Hanging Wall Art, Decorative Sign, Home Office Decor","category":"homeandappliances","retail price":14.92,"sale price":null,"image":"https://m.media-amazon.com/images/I/61jpvq5s02L._AC_SL1500_.jpg","description":"More than just a hanging sign, Honey Dew Gifts Chaos Coordinator funny wooden sign is the perfect gift idea to show appreciation for the person who keeps things together at home or in the office, or hang this wooden sign with other wall decor or hang alone on the door for a touch of humor. It's a simple and rustic hanging plaque that is sure to get noticed by family and guests, and it's especially crafted from premium-quality materials to stand the test of time. This sign comes with a durable jute rope fastened to the back for easy hanging up a wall or on a door. Celebrate your kind of chaos with a wooden sign as a house or office decor. Seriously, it takes a tough man or woman to make a sense out of everyday chaos, and for that, you deserve a plaque!","images":["https://m.media-amazon.com/images/I/61jpvq5s02L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Honey Dew Gifts","source_asin":"B07H5KPVX4","category_path":"Home & Kitchen"},"sku":"BM-677313","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07H5KPVX4","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07H5KPVX4","price_pending":true,"merchant_ready":false});
